import axios from 'axios';

export const LOGIN_HTTP_ERROR = 'LOGIN_HTTP_ERROR'
export const LOGIN_USERNAME_CHANGE = 'LOGIN_USERNAME_CHANGE'
export const LOGIN_PASSWORD_CHANGE = 'LOGIN_PASSWORD_CHANGE'
export const LOGIN_SUBMIT_ENABLE = 'LOGIN_SUBMIT_ENABLE'
export const LOGIN_SUBMIT_DISABLE = 'LOGIN_SUBMIT_DISABLE'


export function loginHttpError(error) {
  return {
    type: LOGIN_HTTP_ERROR,
    error: error
  }
}

export function loginUsernameChange(scUsername) {
  return {
    type: LOGIN_USERNAME_CHANGE,
    scUsername: scUsername
  }
}

export function loginPasswordChange(scPassword) {
  return {
    type: LOGIN_PASSWORD_CHANGE,
    scPassword: scPassword
  }
}


export function loginSubmitEnable() {
  return {
    type: LOGIN_SUBMIT_ENABLE
  }
}

export function loginSubmitDisable() {
  return {
    type: LOGIN_SUBMIT_DISABLE
  }
}

export function handleLoginChange(event) {
    
    return (dispatch, getState) => {
        
        const { name, value } = event.target
        
        if (name === 'scUsername') {
          dispatch(loginUsernameChange(value))
        } else  if (name === 'scPassword') {
          dispatch(loginPasswordChange(value))
        }
        
        if(getState().scUsername && getState().scUsername.length > 0 && getState().scPassword && getState().scPassword.length > 0) {
            dispatch(loginSubmitEnable())
        } else {
            dispatch(loginSubmitDisable())
        }

          
    }
    
}

export function handleLoginSubmit(event) {
    

    return (dispatch, getState) => {

            axios({
                method: 'post',
                url: 'https://scbm.amfdev.co.uk/api/login/',
                headers: {}, 
                data: {
                  scUsername: getState().scUsername,
                  scPassword: getState().scPassword
                }
                })
                .then(json => catchLoginUserNotFound(json, dispatch))
                  .catch(err => {
                    console.log(err);
                  });

                  
    }
    
}


function catchLoginUserNotFound(json, dispatch) {
   //console.log('catchAuthSessionError')
    if (!json.userFound) {
        //dispatch(authSessionError(json.authError))
        throw Error(json.loginError);
    }
    
  return json;
}

